def f1(g):  # nearest other comp by center manhattan
    H,W=len(g),len(g[0]); ba=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=ba and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        n=(a+da,b+db)
                        if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==col and n not in seen:
                            seen.add(n); st.append(n)
                cs=sorted(cells)
                r0=min(p[0] for p in cs); c0=min(p[1] for p in cs)
                cr=sum(p[0] for p in cs)/len(cs); cc=sum(p[1] for p in cs)/len(cs)
                comps.append((col,(r0,c0),cr,cc))
    out=[row[:] for row in g]
    for i,(col,pos,cr,cc) in enumerate(comps):
        r0,c0=pos; r1=max(p[0] for p in pos); c1=max(p[1] for p in pos)
        best=None
        for j,(col2,pos2,cr2,cc2) in enumerate(comps):
            if j==i: continue
            d=max(abs(cr-cr2),abs(cc-cc2))
            if best is None or d<best[0]: best=(d,col2)
        if best:
            r0,c0=pos; r1=max(p[0] for p in pos); c1=max(p[1] for p in pos)
            for dr in range(r0,r1+1):
                for dc in range(c0,c1+1):
                    out[dr][dc]=best[1]
    return out

