    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g):
    H,W=len(g),len(g[0]); ba=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=ba and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        n=(a+da,b+db)
                        if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==col and n not in seen:
                            seen.add(n); st.append(n)
                r0=min(p[0] for p in cells); c0=min(p[1] for p in cells)
                pat=tuple(sorted((a-r0,b-c0) for a,b in cells))
                cr=sum(p[0] for p in cells)/len(cells); cc=sum(p[1] for p in cells)/len(cells)
                out.append({'col':col,'cells':sorted(cells),'r0':r0,'c0':c0,'cr':cr,'cc':cc,'pat':pat,'n':len(cells)})
    return ba,out
def f(A):
    H,W=len(A),len(A[0])
    out=comps(A)
    fam={}
    for v in out: fam.setdefault(v['pat'],[]).append(v)
    R=[row[:] for row in A]
    for p,vlist in fam.items():
        if len(vlist)!=2: continue
        a,b=vlist
        def touches(v):
            for dr,dc in v['cells']:
                if dr in (0,H-1) or dc in (0,W-1): return True
            return False
        chg,par = (a,b) if not touches(a) else (b,a)
        ps=[u for u in out if u not in (chg,par)]
        best=min(ps,key=lambda v:min(max(abs(dr-ddr),abs(dc-ddc)) for dr,dc in chg['cells'] for ddr,ddc in v['cells']))
        col=best['col']
        for dr,dc in chg['cells']: R[dr][dc]=col
    return R
for k in range(1,9):
    Ai=G[f'Demo pair {k} input']; Bo=G[f'Demo pair {k} output']
    R=f(Ai)
    mism=[(r,c,R[r][c],Bo[r][c]) for r in range(len(R)) for c in range(len(R[0])) if R[r][c]!=Bo[r][c]]
    print(k,'OK' if not mism else 'FAIL:',mism[:8])

