import os,re,json
from collections import Counter, defaultdict
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g):
    H,W=len(g),len(g[0]); ba=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=ba and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        n=(a+da,b+db)
                        if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==col and n not in seen:
                            seen.add(n); st.append(n)
                r0=min(p[0] for p in cells); c0=min(p[1] for p in cells)
                pat=tuple(sorted((a-r0,b-c0) for a,b in cells))
                out.append({'col':col,'cells':sorted(cells),'r0':r0,'c0':c0,'pat':pat})
    return out
def gap(a,u):
    return min(max(abs(dr-ddr),abs(dc-ddc)) for dr,dc in a['cells'] for ddr,ddc in u['cells'])
def bt(v,g):
    H,W=len(g),len(g[0])
    return any(r==0 or r==H-1 or c==0 or c==W-1 for r,c in v['cells'])
# Family selection: max border count among twin families; tie-break = larger gap between twins. Changed copy = non-border one; source color = nearest third-party component to changed copy (min Chebyshev), excluding comps of same color as changed copy. Test variants on all demos.
import itertools
for k in range(1,9):
    A=G[f'Demo pair {k} input']; Bo=G[f'Demo pair {k} output']
    cs=comps(A)
    fam=defaultdict(list)
    for v in cs: fam[v['pat']].append(v)
    scored=[]
    for vl in fam.values():
        if len(vl)!=2: continue
        s=sum(bt(v,A) for v in vl)
        scored.append(((s, -gap(vl[0],vl[1])), list(vl)))
    best=max(scored)
    vl=best[1]; a,b=vl
    ca={Bo[r][c] for r,c in a['cells'] if A[r][c]!=Bo[r][c]}
    cb={Bo[r][c] for r,c in b['cells'] if A[r][c]!=Bo[r][c]}
    chg=a if ca else b
    anchor=b if chg==a else a
    tc=None; bestd=10**9
    for v in cs:
        if v is anchor or v['col']==chg['col']: continue
        dd=[max(abs(rr-ar),abs(cc-ac_)) for rr,cc_ in chg['cells'] for ar,ac_ in v['cells']]
        if dd and dd[0]<bestd: bestd=dd[0]; tc=v['col']
    O=[row[:] for row in A]
    for r,c in chg['cells']: O[r][c]=tc
    m=[(r,c,O[r][c],Bo[r][c]) for r in range(len(Bo)) for c in range(len(Bo[0])) if O[r][c]!=Bo[r][c]]
    print(k,'OK' if not m else 'FAIL:',m[:6])
